  "LO-366": {
    "title": "Advanced Syntax: Relative Clauses & Reported Speech ⚙️🔤",
    "desc": "Communicates accurately using appropriate grammatical forms (e.g., clauses, comparison of adjectives, time and tense, active/passive voice, reported speech etc.)",
    "subSkill": "Grammar in Use",
    "audio_script": "Students deconstruct complex sentences: 'The scientist, WHOSE groundbreaking solar research was published in Nature, reported that renewable energy had surpassed fossil fuels.'",
    "story": "Students deconstruct complex sentences: 'The scientist, WHOSE groundbreaking solar research was published in Nature, reported that renewable energy had surpassed fossil fuels.'",
    "instructions": [],
    "questions": [
      {
        "q": "In the sentence: 'The solar engineer, WHOSE research won the global prize, visited our school', what type of clause is 'whose research won the global prize'?",
        "options": [
          "An Adverbial Clause of time",
          "An Imperative Command",
          "A Direct Object Noun Clause",
          "A Non-Defining Relative Clause"
        ],
        "answer": 3,
        "explain": "Relative clauses beginning with who/whose/which add descriptive detail about the preceding noun!"
      },
      {
        "q": "Convert to INDIRECT (Reported) Speech: The doctor said, \"The patient has recovered fully.\"",
        "options": [
          "The doctor said that the patient has recovered fully.",
          "The doctor said that the patient will recover fully.",
          "The doctor said the patient recovers fully.",
          "The doctor said that the patient had recovered fully."
        ],
        "answer": 3,
        "explain": "Present perfect ('has recovered') shifts back to past perfect ('had recovered') in reported speech!"
      },
      {
        "q": "Which sentence demonstrates the correct CONDITIONAL structure (Type 3: impossible past hypothesis)?",
        "options": [
          "If we had left earlier, we will surely catch the morning express train.",
          "If we left much earlier, we can easily catch the morning express train.",
          "If we had left earlier, we would have caught the morning express train.",
          "If we leave earlier today, we would have caught the morning express train."
        ],
        "answer": 2,
        "explain": "Third conditional formula: If + past perfect (had left) ... would have + past participle (would have caught)!"
      }
    ]
  },
