  "LO-396": {
    "title": "Direct & Inverse Proportions: Speed, Time & Work 🏎️⏱️",
    "desc": "Solves problems based on direct and inverse proportions",
    "subSkill": "Ratio & Proportion",
    "audio_script": "If 6 workers can construct a community boundary wall in 12 days, how many days will 12 workers take working at the same pace?",
    "story": "If 6 workers can construct a community boundary wall in 12 days, how many days will 12 workers take working at the same pace?",
    "instructions": [],
    "questions": [
      {
        "q": "Is workers vs time to finish a wall DIRECT or INVERSE proportion? Calculate days for 12 workers:",
        "options": [
          "Direct proportion requiring 24 days",
          "Direct proportion requiring 12 days",
          "Inverse proportion requiring 3 days",
          "Inverse proportion requiring 6 days"
        ],
        "answer": 3,
        "explain": "Inverse proportion: as the number of workers doubles, the time needed is cut in half: 6 days!"
      },
      {
        "q": "A car travels at a constant speed of 60 km/h: in 1 hour it covers 60 km, in 2 hours 120 km, in 3 hours 180 km. Is distance vs time direct or inverse?",
        "options": [
          "Zero proportion",
          "Inverse proportion",
          "Negative proportion",
          "DIRECT PROPORTION"
        ],
        "answer": 3,
        "explain": "Direct proportion: y/x = k (constant). More driving time directly yields proportionally greater distance!"
      },
      {
        "q": "If a car travels from Delhi to Agra in 4 hours at 60 km/h, how fast must it drive to make the trip in 3 hours?",
        "options": [
          "90 km/h",
          "80 km/h",
          "70 km/h",
          "75 km/h"
        ],
        "answer": 1,
        "explain": "Total distance is 240 km. To cover it in 3 hours requires 240 / 3 = 80 km/h!"
      }
    ]
  },
