    "title": "Road to Freedom: Swadeshi, Non-Cooperation & Quit India 🇮🇳🕊️",
    "desc": "Outlines the course of the Indian national movement from the 1870s till Independence",
    "subSkill": "Colonial & Modern India",
    "audio_script": "Students trace the epic trajectory of the Indian National Movement: from the founding of the Indian National Congress in 1885, to the Salt March in 1930, and the historic Quit India clarion call in 1942.",
